package servicio; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.sql.Connection; import java.time.LocalDate; import org.junit.jupiter.api.*; import dao.*; import negocio.*; class IdentidadDeportivaServiceTest { PerfilJugadorDAO p; CategoriaDeportivaDAO c; JugadorCategoriaDAO h; Connection x; IdentidadDeportivaService s; @BeforeEach void init(){p=mock(PerfilJugadorDAO.class);c=mock(CategoriaDeportivaDAO.class);h=mock(JugadorCategoriaDAO.class);x=mock(Connection.class);s=new IdentidadDeportivaService(p,c,h,()->x);} @Test void creaPerfilProvisional() {PerfilJugador r=s.crearProvisional("Ana Perez");assertEquals(EstadoPerfilJugador.PROVISIONAL,r.getEstado());assertNull(r.getClienteId());verify(p).guardar(x,r);} @Test void creaPerfilDefinitivo(){PerfilJugador r=s.crearDefinitivo(7,"Ana Perez");assertEquals(7,r.getClienteId());assertEquals(EstadoPerfilJugador.DEFINITIVO,r.getEstado());} @Test void rechazaClienteInvalido(){assertThrows(IllegalArgumentException.class,()->s.crearDefinitivo(0,"X"));} @Test void asignaCategoriaYCierraAnterior()throws Exception{PerfilJugador pj=new PerfilJugador();pj.setId(5);CategoriaDeportiva cd=new CategoriaDeportiva();cd.setId(6);cd.setActivo(true);when(p.buscar(x,5)).thenReturn(pj);when(c.buscar(x,6)).thenReturn(cd);LocalDate d=LocalDate.of(2026,10,12);JugadorCategoria r=s.asignarCategoria(5,6,d,OrigenJugadorCategoria.ADMINISTRATIVA,"Evaluacion",1L);verify(h).finalizarVigente(x,5,d.minusDays(1));verify(h).guardar(x,r);verify(x).commit();assertEquals(EstadoJugadorCategoria.VIGENTE,r.getEstado());} @Test void rollbackCuandoCategoriaNoExiste()throws Exception{PerfilJugador pj=new PerfilJugador();pj.setId(5);when(p.buscar(x,5)).thenReturn(pj);assertThrows(IllegalArgumentException.class,()->s.asignarCategoria(5,99,LocalDate.now(),OrigenJugadorCategoria.ADMINISTRATIVA,"Motivo",1L));verify(x).rollback();verify(x,never()).commit();} @Test void validaDatosAsignacion(){assertThrows(IllegalArgumentException.class,()->s.asignarCategoria(0,1,LocalDate.now(),OrigenJugadorCategoria.ADMINISTRATIVA,"x",1L));} }
